local ENV=_ENV or (getfenv and getfenv())
local unpackValues=table.unpack or unpack
local function packValues(...) return {n=select('#',...),...} end
local run
run=function(id,u,...)
  local p=P[id]
  local r={}
  local params,k,code=p[1],p[2],p[3]
  for n=1,params do r[n-1]=select(n,...) end
  local pc=1
